    13
    14  int
    15  LLVMFuzzerInitialize(int *argc ATTRIBUTE_UNUSED,
    16                       char ***argv ATTRIBUTE_UNUSED) {
    17      xmlInitParser();
    18      xmlSetGenericErrorFunc(NULL, xmlFuzzErrorFunc);
    19      xmlSetExternalEntityLoader(xmlFuzzEntityLoader);
    20
    21      return 0;
    22  }
    23
    24  int
    25  LLVMFuzzerTestOneInput(const char *data, size_t size) {
    26      static const size_t maxChunkSize = 128;
    27      xmlDocPtr doc;
    28      xmlParserCtxtPtr ctxt;
    29      xmlTextReaderPtr reader;
    30      xmlChar *out;
    31      const char *docBuffer;
    32      size_t docSize, consumed, chunkSize;
    33      int opts, outSize;
    34
    35      xmlFuzzDataInit(data, size);
    36      opts = xmlFuzzReadInt();
    37      /* XML_PARSE_HUGE still causes timeouts. */
    38      opts &= ~XML_PARSE_HUGE;
    39
    40      xmlFuzzReadEntities();
    41      docBuffer = xmlFuzzMainEntity(&docSize);
    42      if (docBuffer == NULL) {
    43          xmlFuzzDataCleanup();
    44          return(0);
    45      }
    46
    47      /* Pull parser */
    48
    49      doc = xmlReadMemory(docBuffer, docSize, NULL, NULL, opts);
    50      if (opts & XML_PARSE_XINCLUDE)
    51          xmlXIncludeProcessFlags(doc, opts);
    52      /* Also test the serializer. */
    53      xmlDocDumpMemory(doc, &out, &outSize);
    54      xmlFree(out);
    55      xmlFreeDoc(doc);
    56
    57      /* Push parser */
    58
    59      ctxt = xmlCreatePushParserCtxt(NULL, NULL, NULL, 0, NULL);
    60      xmlCtxtUseOptions(ctxt, opts);
    61
    62      for (consumed = 0; consumed < docSize; consumed += chunkSize) {
    63          chunkSize = docSize - consumed;
    64          if (chunkSize > maxChunkSize)
    65              chunkSize = maxChunkSize;
    66          xmlParseChunk(ctxt, docBuffer + consumed, chunkSize, 0);
    67      }
    68
    69      xmlParseChunk(ctxt, NULL, 0, 1);
    70      if (opts & XML_PARSE_XINCLUDE)
    71          xmlXIncludeProcessFlags(ctxt->myDoc, opts);
    72      xmlFreeDoc(ctxt->myDoc);
    73      xmlFreeParserCtxt(ctxt);
    74
    75      /* Reader */
    76
    77      reader = xmlReaderForMemory(docBuffer, docSize, NULL, NULL, opts);
    78      while (xmlTextReaderRead(reader) == 1) {
    79          if (xmlTextReaderNodeType(reader) == XML_ELEMENT_NODE) {
    80              int i, n = xmlTextReaderAttributeCount(reader);
    81              for (i=0; i<n; i++) {
    82                  xmlTextReaderMoveToAttributeNo(reader, i);
    83                  while (xmlTextReaderReadAttributeValue(reader) == 1);
    84              }
    85          }
    86      }
    87      xmlFreeTextReader(reader);
    88
    89      /* Cleanup */
    90
    91      xmlFuzzDataCleanup();
    92
    93      return(0);
    94  }
